#!/usr/bin/env python3
"""tools/ai/synonyms.json -> edge/src/synonyms.js (the Edge Function bundle cannot read files at run time)."""
import json, os
H = os.path.dirname(os.path.abspath(__file__))
g = json.load(open(os.path.join(H, '..', 'ai', 'synonyms.json'), encoding='utf-8')).get('groups', [])
open(os.path.join(H, 'edge', 'src', 'synonyms.js'), 'w', encoding='utf-8').write(
    '/* generated by tools/horus/build_synonyms.py from tools/ai/synonyms.json: do not edit */\nexport const SYNONYM_GROUPS = ' + json.dumps(g, ensure_ascii=False) + ';\n')
print('groups:', len(g))
